export const PERCENT_STATS=new Set(['crit','critd','haste','ampF','ampM','cdr','critres','ten','pvp','maxcrit','critdres','ampres','ignoreCritRes','ignoreCritdRes','ignoreAmpRes']);
export const ROLL_GRADES={weak:{label:'Fraco',color:'#a9b4c4'},fair:{label:'Razoável',color:'#70cf94'},good:{label:'Bom',color:'#65cfff'},perfect:{label:'Perfeito',color:'#ffcf6b'},over:{label:'Acima do teto',color:'#ff927e'},unknown:{label:'Teto não informado',color:'#879caf'}};
export function optionCap(item,option,catalog=[]){if(Number.isFinite(option.cap)&&option.cap>0)return option.cap;const source=catalog.find(v=>v.id===item.sourceId),cap=source?.native_caps?.[option.type];if(Number.isFinite(cap)&&cap>0)return cap/(PERCENT_STATS.has(option.type)?100:1);return null;}
export function affixQuality(item,option,catalog=[]){const cap=optionCap(item,option,catalog);if(!cap||!Number.isFinite(option.value)||option.value<0)return {key:'unknown',...ROLL_GRADES.unknown,cap:null,percent:null,ratio:null};const ratio=option.value/cap,perfect=Math.abs(ratio-1)<1e-8,key=ratio>1+1e-8?'over':perfect?'perfect':ratio>=.9?'good':ratio>=.75?'fair':'weak';return {key,...ROLL_GRADES[key],cap,ratio,percent:perfect?100:Math.floor(Math.min(ratio,.999999)*10000)/100};}
export function nativePerfect(item,catalog=[]){return item.options?.length===3&&item.options.every(o=>affixQuality(item,o,catalog).key==='perfect');}
